  const form = document.getElementById('contact-form');
  const fullName = document.getElementById('fullName');
  const email = document.getElementById('email');
  const phone = document.getElementById('phone');
  const status = document.getElementById('form-status');

  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  // Allows digits, spaces, dashes, parentheses, periods, optional leading +. Requires 7-15 digits.
  const phoneRe = /^\+?[\d\s().-]{7,}$/;

  function setError(input, message) {
    const errorEl = document.getElementById(input.id + '-error');
    if (message) {
      input.classList.add('invalid');
      input.setAttribute('aria-invalid', 'true');
      errorEl.textContent = message;
      errorEl.classList.add('visible');
    } else {
      input.classList.remove('invalid');
      input.removeAttribute('aria-invalid');
      errorEl.textContent = '';
      errorEl.classList.remove('visible');
    }
  }

  function validateFullName() {
    const v = fullName.value.trim();
    if (!v) return setError(fullName, 'Full name is required.'), false;
    if (v.length < 2) return setError(fullName, 'Please enter your full name.'), false;
    setError(fullName, '');
    return true;
  }

  function validateEmail() {
    const v = email.value.trim();
    if (!v) return setError(email, 'Email address is required.'), false;
    if (!emailRe.test(v)) return setError(email, 'Please enter a valid email address.'), false;
    setError(email, '');
    return true;
  }

  function validatePhone() {
    const v = phone.value.trim();
    if (!v) {
      setError(phone, '');
      return true;
    }
    const digits = v.replace(/\D/g, '');
    if (!phoneRe.test(v) || digits.length < 7 || digits.length > 15) {
      setError(phone, 'Please enter a valid phone number (e.g. +1 555 123 4567).');
      return false;
    }
    setError(phone, '');
    return true;
  }

  fullName.addEventListener('blur', validateFullName);
  email.addEventListener('blur', validateEmail);
  phone.addEventListener('blur', validatePhone);

  [fullName, email, phone].forEach((input) => {
    input.addEventListener('input', () => {
      if (input.classList.contains('invalid')) {
        if (input === fullName) validateFullName();
        else if (input === email) validateEmail();
        else if (input === phone) validatePhone();
      }
    });
  });

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    status.textContent = '';
    status.classList.remove('success');

    const ok = [validateFullName(), validateEmail(), validatePhone()].every(Boolean);

    if (!ok) {
      status.textContent = 'Please fix the errors above and try again.';
      const firstInvalid = form.querySelector('.invalid');
      if (firstInvalid) firstInvalid.focus();
      return;
    }

    status.textContent = 'Thanks! Your message has been sent.';
    status.classList.add('success');
    form.reset();
  });
})();
